package com.ruoyi.medical.persistence;
import com.ruoyi.medical.identity.*;import com.ruoyi.medical.contracts.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import jakarta.servlet.http.*;import org.springframework.security.core.Authentication;import java.util.*;
public class RuntimeRetentionCancellationControllerTest {
 @Test void authenticationPrecedesBodyAndNoRecoveryBodyAccepted()throws Exception{var identities=mock(ApplicationSessionIdentity.class);var service=mock(RuntimeRetentionCancellation.class);var c=new RuntimeRetentionCancellationController(identities,service,new PermissionSchema());var req=mock(HttpServletRequest.class);var auth=mock(Authentication.class);when(req.getHeaders("X-Schema-Version")).thenAnswer(i->Collections.enumeration(List.of("1.0.0")));when(req.getHeaders("X-Context-Revision")).thenAnswer(i->Collections.enumeration(List.of("1")));when(identities.requireCurrent(req,auth)).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->c.cancel(req,mock(HttpServletResponse.class),auth));verify(req,never()).getInputStream();when(req.getContentLengthLong()).thenReturn(2L);assertThrows(SchemaRejection.class,()->c.recover(req,mock(HttpServletResponse.class),auth));verifyNoInteractions(service);}
 @Test void cancellationErrorsUseFrozenProtocol()throws Exception{var c=new RuntimeRetentionCancellationController(mock(ApplicationSessionIdentity.class),mock(RuntimeRetentionCancellation.class),new PermissionSchema());for(ErrorCode code:List.of(ErrorCode.ACCESS_DENIED,ErrorCode.ACTION_STALE,ErrorCode.IDEMPOTENCY_CONFLICT,ErrorCode.CONTEXT_CHANGED,ErrorCode.SCHEMA_INVALID)){var response=new org.springframework.mock.web.MockHttpServletResponse();if(code==ErrorCode.SCHEMA_INVALID)c.invalid(new SchemaRejection(code),response);else c.denied(new TenantAccessException(code),response);assertEquals(code==ErrorCode.ACCESS_DENIED?403:code==ErrorCode.SCHEMA_INVALID?422:409,response.getStatus());var body=new com.fasterxml.jackson.databind.ObjectMapper().readTree(response.getContentAsByteArray());assertEquals(code.name(),body.required("code").asText());assertEquals(response.getHeader("X-Request-Id"),body.required("request_id").asText());}}
 @Test void readonlyMissingUses200ImmutableEnvelope()throws Exception{var identities=mock(ApplicationSessionIdentity.class);var service=mock(RuntimeRetentionCancellation.class);var json=new PermissionSchema();var c=new RuntimeRetentionCancellationController(identities,service,json);var req=mock(HttpServletRequest.class);var auth=mock(Authentication.class);var actor=mock(ApplicationSessionIdentity.Verified.class);when(identities.requireCurrent(req,auth)).thenReturn(actor);when(req.getHeaders("X-Schema-Version")).thenAnswer(i->Collections.enumeration(List.of("1.0.0")));when(req.getHeaders("X-Context-Revision")).thenAnswer(i->Collections.enumeration(List.of("1")));when(req.getHeaders("Idempotency-Key")).thenAnswer(i->Collections.enumeration(List.of("original-cancel-key")));when(service.recover(actor,"1","original-cancel-key")).thenReturn(json.object().put("schema_version","1.0.0").put("status","NOT_FOUND").putNull("receipt"));var response=new org.springframework.mock.web.MockHttpServletResponse();var result=c.recover(req,response,auth);assertEquals(200,response.getStatus());assertEquals("1",response.getHeader("X-Resource-Revision"));assertEquals("NOT_FOUND",result.at("/data/status").asText());verify(service,never()).cancel(any(),anyString(),anyString(),any());}
 public static void main(String[]args)throws Exception{var t=new RuntimeRetentionCancellationControllerTest();t.authenticationPrecedesBodyAndNoRecoveryBodyAccepted();t.cancellationErrorsUseFrozenProtocol();t.readonlyMissingUses200ImmutableEnvelope();System.out.println("PASS 3 cancellation controller tests");}
}
